/**
 * Tệp âm thanh đã được NHÚNG TRỰC TIẾP DƯỚI DẠNG BASE64 (Zero-file dependency)
 * Giọng đọc: Nam A (Charon) - Trầm ấm, uy quyền, chuẩn phát thanh viên miền Bắc
 * Câu thoại: "Yo hu không nghe rõ câu lệnh, vui lòng đọc lại."
 */

const VI_AUDIO_DATA_URI = "data:audio/wav;base64,";
const EN_AUDIO_DATA_URI = "data:audio/wav;base64,";

export const playSilenceWarning = (outputLanguage: "EN" | "VN" = "VN") => {
  try {
    const audioSrc = outputLanguage === "VN" ? VI_AUDIO_DATA_URI : EN_AUDIO_DATA_URI;
    const audio = new Audio(audioSrc);
    audio.volume = 1.0;

    const playPromise = audio.play();
    if (playPromise !== undefined) {
      playPromise.catch((err) => {
        console.warn("Lỗi phát audio DataURI, chuyển sang SpeechSynthesis dự phòng:", err);
        if (typeof window !== "undefined" && window.speechSynthesis) {
          window.speechSynthesis.cancel();
          const msg = outputLanguage === "VN"
            ? "Yo hu không nghe rõ câu lệnh, vui lòng đọc lại."
            : "Yohu did not hear clearly, please speak again.";
          const utterance = new SpeechSynthesisUtterance(msg);
          utterance.lang = outputLanguage === "VN" ? "vi-VN" : "en-US";
          const voices = window.speechSynthesis.getVoices();
          const viVoice = voices.find(v => v.lang.toLowerCase().startsWith("vi") || v.lang.toLowerCase().includes("viet"));
          if (viVoice) {
            utterance.voice = viVoice;
          }
          window.speechSynthesis.speak(utterance);
        }
      });
    }
  } catch (err) {
    console.error("Voice feedback error:", err);
  }
};

export const formatVoiceTranscript = (transcript: string): string => {
  if (!transcript || !transcript.trim()) return "";

  let formattedText = transcript;

  const malePatterns = [
    /đây là giọng nam/gi,
    /thêm giọng nam/gi,
    /chuyển (?:sang\s+)?giọng nam/gi,
    /đóng vai giọng nam/gi,
    /đọc (?:bằng\s+)?giọng nam/gi,
    /nói (?:bằng\s+)?giọng nam/gi,
    /vai nam/gi,
    /\[?\s*giọng nam\s*\]?/gi
  ];
  for (const pattern of malePatterns) {
    formattedText = formattedText.replace(pattern, " [Giọng Nam] ");
  }

  const femalePatterns = [
    /đây là giọng nữ/gi,
    /thêm giọng nữ/gi,
    /chuyển (?:sang\s+)?giọng nữ/gi,
    /đóng vai giọng nữ/gi,
    /đọc (?:bằng\s+)?giọng nữ/gi,
    /nói (?:bằng\s+)?giọng nữ/gi,
    /vai nữ/gi,
    /\[?\s*giọng nữ\s*\]?/gi
  ];
  for (const pattern of femalePatterns) {
    formattedText = formattedText.replace(pattern, " [Giọng Nữ] ");
  }

  return formattedText
    .replace(/\s+/g, " ")
    .replace(/\[\s*Giọng\s*(Nam|Nữ)\s*\]/gi, (match) => {
      const cleanedTag = match.toUpperCase().includes("NAM") ? "[Giọng Nam]" : "[Giọng Nữ]";
      return " " + cleanedTag + " ";
    })
    .trim();
};
